// src/pages/AdminMode.js
import React, { useEffect, useState } from "react";
import styled from "styled-components";
import { motion } from "framer-motion";
import Sidebar from "../components/Sidebar";
import ExpenseForm from "../components/ExpenseForm";
import { fetchCategories } from "../api/api";

const Container = styled.div`
  display: flex;
  background-color: #f4f6f8;
  min-height: 100vh;
  
  @media (max-width: 768px) {
    flex-direction: column;
  }
`;

const Content = styled(motion.div)`
  padding: 20px;
  flex: 1;
`;

const Header = styled.h2`
  color: #2c3e50;
  margin-bottom: 15px;
`;

const AdminMode = () => {
  const [categories, setCategories] = useState([]);

  const loadCategories = () => {
    fetchCategories()
      .then((data) => {
        console.log("Loaded categories:", data);
        setCategories(data);
      })
      .catch((error) => console.error("Error fetching categories:", error));
  };

  useEffect(() => {
    loadCategories();
  }, []);

  // When a new category is added, refresh the list.
  const handleCategoryAdded = () => {
    loadCategories();
  };

  return (
    <Container>
      <Sidebar />
      <Content
        initial={{ opacity: 0, x: 50 }}
        animate={{ opacity: 1, x: 0 }}
        transition={{ duration: 0.5 }}
      >
        <Header>🤷‍♂️ Admin Dashboard</Header>
        {/* Pass both the category list and refresh callback */}
        <ExpenseForm categories={categories} onCategoryAdded={handleCategoryAdded} />
      </Content>
    </Container>
  );
};

export default AdminMode;
