import React, { useState, useEffect } from "react";
import styled from "styled-components";
import axios from "axios";
import ExpenseChart from "../components/ExpenseChart";
import ComparisonChart from "../components/ComparisonChart";
import ExpenseList from "../components/ExpenseList";
import Sidebar from "../components/Sidebar";

const Container = styled.div`
  display: flex;
  min-height: 100vh;
  font-family: 'Roboto', sans-serif;
  
  @media (max-width: 768px) {
    flex-direction: column;
  }
`;

const MainContent = styled.div`
  flex-grow: 1;
  padding: 20px;
`;

const HeaderWrapper = styled.div`
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
`;

const Title = styled.h1`
  margin: 0;
`;

const ToggleButton = styled.button`
  padding: 8px 16px;
  background-color: #007bff;
  color: #fff;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  margin-top: 10px;
`;

const DateRangeWrapper = styled.div`
  margin-top: 20px;
  display: flex;
  align-items: center;
  flex-wrap: wrap;
`;

const Label = styled.label`
  margin-right: 10px;
`;

const Select = styled.select`
  padding: 6px;
  border-radius: 4px;
`;

const SummaryCard = styled.div`
  margin-top: 20px;
  padding: 20px;
  background-color: #f7f7f7;
  border-radius: 8px;
`;

const BreakdownGrid = styled.div`
  margin-top: 20px;
  display: flex;
  gap: 15px;
  flex-wrap: wrap;
`;

const BreakdownCard = styled.div`
  flex: 1 0 150px;
  padding: 10px;
  background-color: #fff;
  border: 1px solid #ddd;
  border-radius: 8px;
  text-align: center;
`;

const ChartsWrapper = styled.div`
  margin-top: 30px;
`;

const ChartsGrid = styled.div`
  display: flex;
  gap: 20px;
  flex-wrap: wrap;
`;

const ChartCard = styled.div`
  flex: 1;
  min-width: 300px;
  border: 1px solid #ddd;
  border-radius: 8px;
  padding: 15px;
`;

const formatDate = (date) => date.toISOString().split("T")[0];

const today = new Date();
const sixDaysAgo = new Date();
sixDaysAgo.setDate(today.getDate() - 1);

const API_BASE_URL = "https://54.156.153.175:8081/api";

const ViewMode = () => {
  const [startDate, setStartDate] = useState(formatDate(sixDaysAgo));
  const [endDate, setEndDate] = useState(formatDate(today));
  const [totalExpense, setTotalExpense] = useState(0);
  const [categoryBreakdown, setCategoryBreakdown] = useState([]);
  const [viewMode, setViewMode] = useState("charts");
  const [compareType, setCompareType] = useState("daily");

  useEffect(() => {
    fetchSummary();
    fetchAndGroupExpenses();
  }, [startDate, endDate]);

  const fetchSummary = async () => {
    try {
      const url = `${API_BASE_URL}/expenses/summary`;
      console.debug(`DEBUG: Calling ${url} with start=${startDate} & end=${endDate}`);
      const res = await axios.get(url, { params: { start: startDate, end: endDate } });
      console.debug("DEBUG: Total expenditure response:", res.data);
      if (res.data && typeof res.data.totalExpense === "number") {
        setTotalExpense(res.data.totalExpense);
      } else {
        console.error("DEBUG: Unexpected total expenditure response:", res.data);
      }
    } catch (err) {
      console.error("ERROR: Failed to fetch total expenditure:", err);
    }
  };

  const fetchAndGroupExpenses = async () => {
    try {
      const url = `${API_BASE_URL}/expenses/between`;
      console.debug(`DEBUG: Calling ${url} with start=${startDate} & end=${endDate}`);
      const res = await axios.get(url, { params: { start: startDate, end: endDate } });
      console.debug("DEBUG: Expenses response:", res.data);
      if (Array.isArray(res.data)) {
        const breakdown = {};
        res.data.forEach((item) => {
          const catName = item.category?.category || "Unknown";
          breakdown[catName] = (breakdown[catName] || 0) + Number(item.expense);
        });
        const breakdownArr = Object.keys(breakdown).map((cat) => ({
          category: cat,
          amount: breakdown[cat],
        }));
        console.debug("DEBUG: Calculated category breakdown:", breakdownArr);
        setCategoryBreakdown(breakdownArr);
      } else {
        console.error("DEBUG: Unexpected expenses response:", res.data);
      }
    } catch (err) {
      console.error("ERROR: Failed to fetch expenses for breakdown:", err);
    }
  };

  const handlePresetChange = (e) => {
    const preset = e.target.value;
    if (preset === "1") {
      setStartDate(endDate);
    } else if (preset === "7") {
      const dt = new Date(endDate);
      dt.setDate(dt.getDate() - 6);
      setStartDate(formatDate(dt));
    } else if (preset === "30") {
      const dt = new Date(endDate);
      dt.setDate(dt.getDate() - 29);
      setStartDate(formatDate(dt));
    }
  };

  return (
    <Container>
      <Sidebar />
      <MainContent>
        <HeaderWrapper>
          <Title>Expense Tracker - View Mode</Title>
          <ToggleButton onClick={() => setViewMode(viewMode === "charts" ? "list" : "charts")}>
            {viewMode === "charts" ? "Switch to List View" : "Switch to Charts View"}
          </ToggleButton>
        </HeaderWrapper>

        <DateRangeWrapper>
          <Label>Preset Date Range:</Label>
          <Select onChange={handlePresetChange}>
            <option value="1">Last 1 Day</option>
            <option value="7">Last 7 Days</option>
            <option value="30">Last 30 Days</option>
          </Select>
        </DateRangeWrapper>

        <SummaryCard>
          <h2>Total Expenditure</h2>
          <p style={{ fontSize: "1.5rem", fontWeight: "bold" }}>
            ${totalExpense.toFixed(2)}
          </p>
        </SummaryCard>

        <BreakdownGrid>
          {categoryBreakdown.map((item) => (
            <BreakdownCard key={item.category}>
              <h4>{item.category}</h4>
              <p>${item.amount.toFixed(2)}</p>
            </BreakdownCard>
          ))}
        </BreakdownGrid>

        {viewMode === "charts" ? (
          <ChartsWrapper>
            <ChartsGrid>
              <ChartCard>
                <h3 style={{ textAlign: "center" }}>Expense Trend by Category</h3>
                <ExpenseChart categoryBreakdown={categoryBreakdown} />
              </ChartCard>
              <ChartCard>
                <HeaderWrapper>
                  <h3>Expense Comparison</h3>
                  <Select onChange={(e) => setCompareType(e.target.value)} value={compareType}>
                    <option value="daily">Daily</option>
                    <option value="weekly">Weekly</option>
                    <option value="monthly">Monthly</option>
                  </Select>
                </HeaderWrapper>
                <ComparisonChart type={compareType} endDate={endDate} />
              </ChartCard>
            </ChartsGrid>
          </ChartsWrapper>
        ) : (
          <div style={{ marginTop: "30px" }}>
            <ExpenseList startDate={startDate} endDate={endDate} />
          </div>
        )}
      </MainContent>
    </Container>
  );
};

export default ViewMode;
