import React, { useEffect, useState } from "react";
import { Line } from "react-chartjs-2";
import styled from "styled-components";
import { fetchExpenses } from "../api/api";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  LineElement,
  PointElement,
  Tooltip,
  Legend,
  Filler,
} from "chart.js";

ChartJS.register(CategoryScale, LinearScale, LineElement, PointElement, Tooltip, Legend, Filler);

const ChartContainer = styled.div`
  height: 300px;
`;

const ComparisonChart = ({ type, endDate }) => {
  const [chartData, setChartData] = useState(null);
  const [loading, setLoading] = useState(true);

  const periodLengths = {
    daily: 1,
    weekly: 7,
    monthly: 30,
  };

  useEffect(() => {
    const getComparisonData = async () => {
      setLoading(true);
      try {
        const periodLength = periodLengths[type] || 7;
        const currentEnd = new Date(endDate);
        const currentStart = new Date(endDate);
        currentStart.setDate(currentStart.getDate() - (periodLength - 1));

        const previousEnd = new Date(currentStart);
        previousEnd.setDate(previousEnd.getDate() - 1);
        const previousStart = new Date(previousEnd);
        previousStart.setDate(previousStart.getDate() - (periodLength - 1));

        const currStartStr = currentStart.toISOString().split("T")[0];
        const currEndStr = currentEnd.toISOString().split("T")[0];
        const prevStartStr = previousStart.toISOString().split("T")[0];
        const prevEndStr = previousEnd.toISOString().split("T")[0];

        console.debug(`DEBUG: Current Period: ${currStartStr} to ${currEndStr}`);
        console.debug(`DEBUG: Previous Period: ${prevStartStr} to ${prevEndStr}`);

        const [currData, prevData] = await Promise.all([
          fetchExpenses(currStartStr, currEndStr),
          fetchExpenses(prevStartStr, prevEndStr),
        ]);
        console.debug("DEBUG: Current period data:", currData);
        console.debug("DEBUG: Previous period data:", prevData);

        const getDatesInRange = (startStr, endStr) => {
          const start = new Date(startStr);
          const end = new Date(endStr);
          const dates = [];
          const current = new Date(start);
          while (current <= end) {
            dates.push(current.toISOString().split("T")[0]);
            current.setDate(current.getDate() + 1);
          }
          return dates;
        };

        const currentDates = getDatesInRange(currStartStr, currEndStr);
        const previousDates = getDatesInRange(prevStartStr, prevEndStr);

        const bucketExpenses = (data, dates) => {
          const bucket = {};
          dates.forEach((d) => (bucket[d] = 0));
          if (Array.isArray(data)) {
            data.forEach((item) => {
              const dateKey = item.date;
              if (bucket.hasOwnProperty(dateKey)) {
                bucket[dateKey] += Number(item.expense);
              }
            });
          }
          return dates.map((d) => bucket[d]);
        };

        const currentTotals = bucketExpenses(currData, currentDates);
        const previousTotals = bucketExpenses(prevData, previousDates);

        setChartData({
          labels: currentDates,
          datasets: [
            {
              label: `Current (${currStartStr} - ${currEndStr})`,
              data: currentTotals,
              borderColor: "green",
              backgroundColor: "rgba(0,128,0,0.1)",
              fill: true,
            },
            {
              label: `Previous (${prevStartStr} - ${prevEndStr})`,
              data: previousTotals,
              borderColor: "red",
              backgroundColor: "rgba(255,0,0,0.1)",
              fill: true,
            },
          ],
        });
      } catch (err) {
        console.error("ERROR: Failed to fetch comparison data:", err);
      }
      setLoading(false);
    };

    getComparisonData();
  }, [type, endDate]);

  const options = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: { legend: { position: "bottom" } },
  };

  return (
    <ChartContainer>
      {loading ? (
        <p>Loading comparison data...</p>
      ) : chartData ? (
        <Line data={chartData} options={options} />
      ) : (
        <p>No data available.</p>
      )}
    </ChartContainer>
  );
};

export default ComparisonChart;
