import React, { useEffect } from "react";
import { Bar } from "react-chartjs-2";
import styled from "styled-components";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Tooltip,
  Legend,
} from "chart.js";

ChartJS.register(CategoryScale, LinearScale, BarElement, Tooltip, Legend);

const ChartContainer = styled.div`
  height: 300px;
`;

const ExpenseChart = ({ categoryBreakdown }) => {
  useEffect(() => {
    console.debug("DEBUG: Rendering ExpenseChart with categoryBreakdown:", categoryBreakdown);
  }, [categoryBreakdown]);

  const data = {
    labels: categoryBreakdown.map((item) => item.category),
    datasets: [
      {
        label: "Expense Amount",
        data: categoryBreakdown.map((item) => item.amount),
        backgroundColor: "rgba(54, 162, 235, 0.6)",
      },
    ],
  };

  const options = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: { legend: { display: false } },
  };

  return (
    <ChartContainer>
      <Bar data={data} options={options} />
    </ChartContainer>
  );
};

export default ExpenseChart;
