import axios from "axios";

const API_BASE_URL = "https://54.156.153.175:8081/api";

const api = axios.create({
  baseURL: API_BASE_URL,
  headers: {
    "Content-Type": "application/json",
  },
});

export const fetchExpenses = async (start, end) => {
  try {
    const response = await api.get("/expenses/between", { params: { start, end } });
    return response.data;
  } catch (error) {
    console.error("Error fetching expenses:", error);
    return { error: error.message };
  }
};

export const fetchTotalExpenditure = async (range) => {
  try {
    const response = await api.get("/expenses/total", { params: { range } });
    return response.data;
  } catch (error) {
    console.error("Error fetching total expenditure:", error);
    return { error: error.message };
  }
};

export const fetchComparison = async (type) => {
  try {
    const response = await api.get("/expenses/compare", { params: { type } });
    return response.data;
  } catch (error) {
    console.error("Error fetching comparison data:", error);
    return { error: error.message };
  }
};

export const fetchCategories = async () => {
  try {
    const response = await api.get("/categories");
    return response.data;
  } catch (error) {
    console.error("Error fetching categories:", error);
    return { error: error.message };
  }
};

export const addExpense = async (expenseData) => {
  try {
    const response = await api.post("/expenses", expenseData);
    return response.data;
  } catch (error) {
    console.error("Error adding expense:", error);
    return { error: error.message };
  }
};

export const addCategory = async (categoryData) => {
  try {
    const response = await api.post("/categories", categoryData);
    return response.data;
  } catch (error) {
    console.error("Error adding category:", error);
    return { error: error.message };
  }
};

export default api;
