import React, { useState } from "react";
import { addExpense } from "../api/api";
import { motion } from "framer-motion";
import styled from "styled-components";
import CategoryForm from "./CategoryForm";
import { toast } from "react-toastify";

// Styled components for the form
const Form = styled(motion.form)`
  background: #fff;
  padding: 20px;
  border-radius: 12px;
  box-shadow: 0 6px 15px rgba(0, 0, 0, 0.1);
  margin-bottom: 20px;
  max-width: 500px;
  margin: 20px auto;
`;

const GridContainer = styled.div`
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 15px;
  margin-bottom: 15px;
`;

const Input = styled(motion.input)`
  width: 100%;
  padding: 12px;
  border: 1px solid #ccc;
  border-radius: 8px;
  outline: none;
  transition: border-color 0.3s ease;
`;

const Select = styled(motion.select)`
  width: 100%;
  padding: 12px;
  border: 1px solid #ccc;
  border-radius: 8px;
  outline: none;
  transition: border-color 0.3s ease;
`;

const CategoryContainer = styled.div`
  display: flex;
  align-items: center;
`;

const PlusButton = styled.button`
  margin-left: 8px;
  background: transparent;
  border: none;
  font-size: 24px;
  cursor: pointer;
  color: #3498db;
`;

const Button = styled(motion.button)`
  width: 100%;
  padding: 14px;
  background: #27ae60;
  color: white;
  font-weight: bold;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  font-size: 16px;
`;

const ModalOverlay = styled.div`
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.5);
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 1000;
`;

const ModalContent = styled.div`
  background: #fff;
  padding: 20px;
  border-radius: 8px;
  width: 90%;
  max-width: 500px;
  position: relative;
`;

const ExpenseForm = ({ categories = [], onCategoryAdded }) => {
  const [form, setForm] = useState({
    date: "",
    expense: "",
    note: "",
    category: { id: "", version: 0 },
  });

  const [isCategoryModalOpen, setIsCategoryModalOpen] = useState(false);

  const handleChange = (e) => {
    const { name, value } = e.target;
    if (name === "category_id") {
      const selectedCategory = categories.find((cat) => cat.id === parseInt(value));
      if (selectedCategory) {
        setForm((prevForm) => ({
          ...prevForm,
          category: { id: selectedCategory.id, version: selectedCategory.version },
        }));
      } else {
        setForm((prevForm) => ({
          ...prevForm,
          category: { id: "", version: 0 },
        }));
      }
    } else {
      setForm((prevForm) => ({ ...prevForm, [name]: value }));
    }
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (form.category.id && form.expense && form.date) {
      addExpense(form)
        .then(() => {
          toast.success("Expense added successfully!");
          setForm({
            date: "",
            expense: "",
            note: "",
            category: { id: "", version: 0 },
          });
        })
        .catch((error) => {
          console.error("Error adding expense:", error);
          toast.error("Failed to add expense. Please try again.");
        });
    } else {
      toast.warn("Please fill in all required fields.");
    }
  };

  return (
    <>
      <Form
        onSubmit={handleSubmit}
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5 }}
      >
        <h3>💼 Add Expense</h3>
        <GridContainer>
          <Input
            type="date"
            name="date"
            value={form.date}
            onChange={handleChange}
            whileFocus={{ scale: 1.02, borderColor: "#3498db" }}
            required
          />

          <CategoryContainer>
            <Select
              name="category_id"
              value={form.category.id}
              onChange={handleChange}
              whileFocus={{ scale: 1.02, borderColor: "#3498db" }}
              required
            >
              <option value="">Select Category</option>
              {categories && categories.length > 0 ? (
                categories.map((cat) => (
                  <option key={cat.id} value={cat.id}>
                    {cat.icon} {cat.category}
                  </option>
                ))
              ) : (
                <option disabled>No Categories Available</option>
              )}
            </Select>
            <PlusButton type="button" onClick={() => setIsCategoryModalOpen(true)}>
              +
            </PlusButton>
          </CategoryContainer>

          <Input
            type="number"
            name="expense"
            placeholder="Amount"
            value={form.expense}
            onChange={handleChange}
            whileFocus={{ scale: 1.02, borderColor: "#3498db" }}
            required
          />
          <Input
            type="text"
            name="note"
            placeholder="Note (optional)"
            value={form.note}
            onChange={handleChange}
            whileFocus={{ scale: 1.02, borderColor: "#3498db" }}
          />
        </GridContainer>

        <Button
          type="submit"
          whileHover={{ scale: 1.05, backgroundColor: "#2ecc71" }}
          whileTap={{ scale: 0.95 }}
          transition={{ type: "spring", stiffness: 300 }}
        >
          💰 Add Expense
        </Button>
      </Form>

      {/* Modal popup for adding a new category */}
      {isCategoryModalOpen && (
        <ModalOverlay>
          <ModalContent>
            <CategoryForm
              onCategoryAdded={() => {
                if (onCategoryAdded) onCategoryAdded();
                setIsCategoryModalOpen(false);
                
              }}
            />
            <Button
              type="button"
              onClick={() => setIsCategoryModalOpen(false)}
              style={{ marginTop: "10px", background: "#e74c3c" }}
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
            >
              Close
            </Button>
          </ModalContent>
        </ModalOverlay>
      )}
    </>
  );
};

export default ExpenseForm;
