import React, { useEffect, useState } from "react";
import styled from "styled-components";
import { fetchExpenses } from "../api/api";

const Container = styled.div`
  margin: 20px;
`;

const Title = styled.h2`
  margin-bottom: 1rem;
`;

const Table = styled.table`
  width: 100%;
  border-collapse: collapse;
`;

const Th = styled.th`
  border: 1px solid #ddd;
  padding: 8px;
`;

const Td = styled.td`
  border: 1px solid #ddd;
  padding: 8px;
`;

const ExpenseList = ({ startDate, endDate }) => {
  const [expenses, setExpenses] = useState([]);

  useEffect(() => {
    const getExpenses = async () => {
      console.debug(`DEBUG: Fetching expenses for list view from ${startDate} to ${endDate}`);
      const data = await fetchExpenses(startDate, endDate);
      console.debug("DEBUG: ExpenseList API response:", data);
      if (data && !data.error) {
        setExpenses(data);
      } else {
        console.error("DEBUG: Unexpected ExpenseList response:", data);
      }
    };
    getExpenses();
  }, [startDate, endDate]);

  return (
    <Container>
      <Title>Expense List</Title>
      <Table>
        <thead>
          <tr>
            <Th>Date</Th>
            <Th>Category</Th>
            <Th>Expense</Th>
            <Th>Note</Th>
          </tr>
        </thead>
        <tbody>
          {expenses.map((exp) => (
            <tr key={exp.id}>
              <Td>{exp.date}</Td>
              <Td>{exp.category?.category || "N/A"}</Td>
              <Td>${Number(exp.expense).toFixed(2)}</Td>
              <Td>{exp.note}</Td>
            </tr>
          ))}
        </tbody>
      </Table>
    </Container>
  );
};

export default ExpenseList;
