import React from "react";
import { Link } from "react-router-dom";
import styled from "styled-components";
import { motion } from "framer-motion";

const SidebarContainer = styled(motion.div)`
  background: #34495e;
  color: #ecf0f1;
  padding: 20px;
  width: 200px;
  min-height: 100vh;
  
  @media (max-width: 768px) {
    width: 100%;
    min-height: auto;
  }
`;

const Header = styled.h3`
  font-size: 20px;
  margin-bottom: 20px;
`;

const Nav = styled.nav`
  display: flex;
  flex-direction: column;
  gap: 10px;
`;

const StyledLink = styled(Link)`
  color: #ecf0f1;
  text-decoration: none;
  font-size: 16px;
  padding: 8px;
  border-radius: 4px;
  background: #2c3e50;
  
  &:hover {
    background: #1a252f;
  }
`;

const Sidebar = () => {
  return (
    <SidebarContainer
      initial={{ x: -100 }}
      animate={{ x: 0 }}
      transition={{ type: "spring", stiffness: 50 }}
    >
      <Header>⚙️ Admin Panel</Header>
      <Nav>
        <StyledLink to="/">View Mode</StyledLink>
        <StyledLink to="/admin">Admin Mode</StyledLink>
      </Nav>
    </SidebarContainer>
  );
};

export default Sidebar;
